{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C03"],
      "claim": "Compound 40 (NA-014), a piperazine amide with a benzonitrile and phenethyl amide, showed a brain-to-plasma ratio of 1.32 in mice after IP dosing, directly demonstrating CNS penetration for a close structural relative.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "A piperazine amide H3 receptor ligand crossed the BBB with a brain-to-plasma ratio of ~1:1 in rats, supporting CNS access for this piperazine-acyl scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "PF-5274857, a piperazine amide, produced significant intact CSF concentrations after oral dosing, confirming meaningful BBB penetration in vivo.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "ASN90, a piperazine amide with heteroaromatic substituents, had a brain/plasma ratio of ~1 and CSF levels matching free plasma, indicating passive diffusion across the BBB.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C06"],
      "claim": "A larger peptide-like piperazine amide showed low brain uptake after IV injection, but its additional H-bond donors and polar bulk are not present in the query, limiting transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C08"],
      "claim": "A highly functionalized piperazine amide was unable to penetrate rat brain, but its larger size and multiple polar groups contrast with the query's neutral, low-TPSA profile.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a neutral, low-TPSA piperazine amide with no HBD and moderate lipophilicity; multiple direct in vivo analogues with the same piperazine-acyl and aromatic-nitrile motifs show brain-to-plasma ratios around 1 or significant CSF exposure. The few impermeable analogues are larger and more polar and do not transfer to the query. Prediction: pass.",
  "evidence_gaps": [
    "No direct experimental measurement for the exact query molecule.",
    "Morgan similarities to evidence molecules are low (0.22-0.27), limiting quantitative transferability.",
    "No P-gp/BCRP efflux data for the query.",
    "No CSF or unbound brain concentration data for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

